package org.credivel.news;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="news",indexes={@Index(name="idx_news_slug",columnList="slug",unique=true),@Index(name="idx_news_publication",columnList="status,publishedAt")}) public class News {
@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=255) private String title; @Column(nullable=false,length=280,unique=true) private String slug; @Column(nullable=false,length=800) private String summary; @Lob @Column(nullable=false) private String content; @Column(nullable=false,length=1000) private String imageUrl; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private NewsClassification classification; @Column(nullable=false,length=180) private String source; @Column(length=160) private String author; @Column(nullable=false,length=100) private String category; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private NewsStatus status=NewsStatus.DRAFT; @Column(nullable=false) private long views=0; private Instant publishedAt; @Column(nullable=false) private Instant updatedAt;
@PrePersist void onCreate(){if(updatedAt==null)updatedAt=Instant.now();}@PreUpdate void onUpdate(){updatedAt=Instant.now();}
public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getSlug(){return slug;} public void setSlug(String v){slug=v;} public String getSummary(){return summary;} public void setSummary(String v){summary=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public NewsClassification getClassification(){return classification;} public void setClassification(NewsClassification v){classification=v;} public String getSource(){return source;} public void setSource(String v){source=v;} public String getAuthor(){return author;} public void setAuthor(String v){author=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public NewsStatus getStatus(){return status;} public void setStatus(NewsStatus v){status=v;} public long getViews(){return views;} public void setViews(long v){views=v;} public Instant getPublishedAt(){return publishedAt;} public void setPublishedAt(Instant v){publishedAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;}}
